using System;
using System.Linq;

namespace Ascendant.CelestialDial
{
    public static class ObservatoryCopy
    {
        public const string ObsDoor = "Wait. That door has not answered anyone since he left.\nThe Observatory, seeker. It seems the Library thinks you are ready for the sky."; // Claude's draft (Stage 2 spec, Nov 5); owner rewrites
        public const string ObsFirst = "The Observatory. Mind your step, the floor is old brass under older dust.\nThose spheres above us are the planets, dark since he left. The orrery is waiting; tap it when you are ready."; // Claude's draft (Stage 2 spec, Nov 5); owner rewrites
        public const string U21Intro = "The signs taught you how a thing is done, apprentice. The planets will teach you what is doing it.\nTen of them, each with a symbol and a work of its own. I shall show you the symbols first. Tell me whose each one is."; // Claude's draft (Stage 2 spec, Nov 5); owner rewrites
        public const string U21Nudge = "Look again, pupil. Some of these symbols are near twins. Find the stroke that sets this one apart."; // Claude's draft (Stage 2 spec, Nov 5); owner rewrites
        public const string U21Reveal = "This one is {planet}'s. Keep it close, apprentice; you will meet it on every chart you ever read."; // Claude's draft (Stage 2 spec, Nov 5); owner rewrites
        public const string U21PartB = "Now the harder half, pupil. Every planet has its work. The orrery will name a work, and you shall turn the brass until the sphere that does it sits under the bracket, then press Seal."; // Claude's draft (Stage 2 spec, Nov 5); owner rewrites
        public const string U21BNudge = "Read the work again, apprentice, then look at each symbol as it passes the bracket."; // Claude's draft (Stage 2 spec, Nov 5); owner rewrites
        public const string U21BRule = "Each planet keeps one work. The Sun is, the Moon feels, Mercury thinks, Venus values, Mars acts.\nJupiter expands, Saturn structures, Uranus awakens, Neptune dissolves, Pluto transforms."; // Claude's draft (Stage 2 spec, Nov 5); owner rewrites
        public const string U21BShow = "Here. To {verb} is {planet}'s work, and this is its sphere. Turn to it and press Seal."; // Claude's draft (Stage 2 spec, Nov 5); owner rewrites
        public const string Key5Line = "Ten symbols, ten works, and most of them you found without my hand on the brass. The orrery knows you now, seeker.\nLook, a Key rises from the spheres. Keeper Key 5 is yours."; // Claude's draft (Stage 2 spec, Nov 5); owner rewrites
        public const string Key5Paused = "The spheres are named, though I confess my hand turned the brass more than yours. The Key shall wait, initiate.\nStudy your journal, and when you return we shall turn it again."; // Claude's draft (Stage 2 spec, Nov 5); owner rewrites
        public const string HubKey5 = "Five Keys, seeker. The orrery has its names back, and I could swear the Observatory runs warmer for it.\nThe Chamber will want to see what you carry."; // Claude's draft (Stage 2 spec, Nov 5); owner rewrites
        public const string HubSpent5 = "Five locks turned. The second Book shifts in its case, initiate; I can hear its pages from here.\nThe orrery has something else to ask of you."; // Claude's draft (Stage 2 spec, Nov 5); owner rewrites
        public const string U22Intro = "The planets do not keep one pace, apprentice. The Moon crosses a sign in two days and a half. Pluto can take thirty years.\nThe spheres have slipped their rings. Set each one on the ring that matches its pace, the swiftest nearest the centre."; // Claude's draft (Stage 2 spec, Nov 5); owner rewrites
        public const string U22Nudge = "Ask how long this one lingers in a single sign, pupil, and place it by that."; // Claude's draft (Stage 2 spec, Nov 5); owner rewrites
        public const string U22Rule = "The Moon is swiftest. The Sun, Mercury and Venus keep close company, about a month to a sign. Mars takes near two months, Jupiter a year, Saturn two and a half.\nThen Uranus seven years, Neptune fourteen, and Pluto longest of all."; // Claude's draft (Stage 2 spec, Nov 5); owner rewrites
        public const string U22Show = "This one belongs here, apprentice. Watch where it sits, and the next will come easier."; // Claude's draft (Stage 2 spec, Nov 5); owner rewrites
        public const string Retro = "One more mark you will meet on every chart, pupil: \u211e. A planet keeps its course, but seen from the Earth it can seem to slide backward for a while, and this mark tells you so.\nWhat that means in a reading can wait."; // Claude's draft (Stage 2 spec, Nov 5); owner rewrites
        public const string U22Bands = "Astrologers of our day sort the planets into four companies. The older traditions knew seven wandering lights and drew no such lines, so hold these loosely, seeker.\nThe two lights, Sun and Moon. The personal planets, Mercury, Venus and Mars. The social pair, Jupiter and Saturn. The outer three, Uranus, Neptune and Pluto. Mark each sphere with its company."; // Claude's draft (Stage 2 spec, Nov 5); owner rewrites
        public const string U22BandNudge = "Think of pace, pupil. The nearer and swifter a planet, the closer it sits to one person's life."; // Claude's draft (Stage 2 spec, Nov 5); owner rewrites
        public const string U22BandReveal = "{Planet} belongs with {company}, apprentice. Mark it there and carry on."; // Claude's draft (Stage 2 spec, Nov 5); owner rewrites
        public const string Key6Line = "Every sphere on its ring and every ring in its company. You see now why the Moon is yours alone and Pluto belongs to a generation, initiate.\nKeeper Key 6 is yours. The second Book has been waiting for it."; // Claude's draft (Stage 2 spec, Nov 5); owner rewrites
        public const string Key6Paused = "The orrery is set, though more by my hand than yours, seeker. The Key will keep.\nRead your journal's planets, and we shall set the spheres again when you return."; // Claude's draft (Stage 2 spec, Nov 5); owner rewrites
        public const string HubKey6 = "Six Keys, initiate. Every sphere sits on its ring.\nTake it to the Books. The second one has been listening for your step."; // Claude's draft (Stage 2 spec, Nov 5); owner rewrites
        public const string ChamberBook2 = "The second Book opens. Two of seven, seeker.\nHe would have stood where you stand and said nothing for a long while."; // Claude's draft (Stage 2 spec, Nov 5); owner rewrites
        public const string ChamberObsCard = "The Observatory's lower floor is awake. The Library remembers, and the rest remains sealed, for now."; // Claude's draft (Stage 2 spec, Nov 5); owner rewrites
        public const string HubObsWhole = "Six Keys spent, seeker. Two Books breathe, and the spheres in the Observatory hold their light.\nRest. The Library has more to show you, and it will choose its moment."; // Claude's draft (Stage 2 spec, Nov 5); owner rewrites
        public static string Pose(string id) { switch(id) { case "ObsDoor": return "moved"; case "ObsFirst": return "explain"; case "U21Intro": return "explain"; case "U21Nudge": return "calm"; case "U21Reveal": return "explain"; case "U21PartB": return "explain"; case "U21BNudge": return "calm"; case "U21BRule": return "explain"; case "U21BShow": return "explain"; case "Key5Line": return "moved"; case "Key5Paused": return "warm"; case "HubKey5": return "warm"; case "HubSpent5": return "wry"; case "U22Intro": return "explain"; case "U22Nudge": return "calm"; case "U22Rule": return "explain"; case "U22Show": return "explain"; case "Retro": return "wry"; case "U22Bands": return "explain"; case "U22BandNudge": return "calm"; case "U22BandReveal": return "explain"; case "Key6Line": return "moved"; case "Key6Paused": return "warm"; case "HubKey6": return "warm"; case "ChamberBook2": return "moved"; case "ChamberObsCard": return ""; case "HubObsWhole": return "calm"; default: return "explain"; } }
    }
}
